/* ****************************************************************************************************************** */
/*                                                                                                                    */
/*                                         Analog to digital converter (ADC)                                          */
/*                                                                                                                    */
/* ****************************************************************************************************************** */
#define ADC_COMMON_COUNT         (2U)      /*!< Number of ADC common instances */
#define ADC_INST_IN_COMMON_COUNT (2U)      /*!< Number of ADC instances within ADC common instance.
                                                Note: maximum number for all common instances (in case of multiple ADC
                                                      common instances, some can encompass less ADC instances). */
#define ADC_MULTIMODE_SUPPORT    (1U)      /*!< Device featuring ADC multimode */

/* *************************************  Bit definition for ADC_ISR register  ************************************** */
#define ADC_ISR_ADRDY_Pos         (0U)
#define ADC_ISR_ADRDY_Msk         (0x1UL << ADC_ISR_ADRDY_Pos)           /*!< 0x00000001 */
#define ADC_ISR_ADRDY             ADC_ISR_ADRDY_Msk                      /*!< ADC ready */
#define ADC_ISR_EOSMP_Pos         (1U)
#define ADC_ISR_EOSMP_Msk         (0x1UL << ADC_ISR_EOSMP_Pos)           /*!< 0x00000002 */
#define ADC_ISR_EOSMP             ADC_ISR_EOSMP_Msk                      /*!< End of sampling flag */
#define ADC_ISR_EOC_Pos           (2U)
#define ADC_ISR_EOC_Msk           (0x1UL << ADC_ISR_EOC_Pos)             /*!< 0x00000004 */
#define ADC_ISR_EOC               ADC_ISR_EOC_Msk                        /*!< End of conversion flag */
#define ADC_ISR_EOS_Pos           (3U)
#define ADC_ISR_EOS_Msk           (0x1UL << ADC_ISR_EOS_Pos)             /*!< 0x00000008 */
#define ADC_ISR_EOS               ADC_ISR_EOS_Msk                        /*!< End of regular sequence flag */
#define ADC_ISR_OVR_Pos           (4U)
#define ADC_ISR_OVR_Msk           (0x1UL << ADC_ISR_OVR_Pos)             /*!< 0x00000010 */
#define ADC_ISR_OVR               ADC_ISR_OVR_Msk                        /*!< ADC overrun */
#define ADC_ISR_JEOC_Pos          (5U)
#define ADC_ISR_JEOC_Msk          (0x1UL << ADC_ISR_JEOC_Pos)            /*!< 0x00000020 */
#define ADC_ISR_JEOC              ADC_ISR_JEOC_Msk                       /*!< Injected channel end of conversion flag */
#define ADC_ISR_JEOS_Pos          (6U)
#define ADC_ISR_JEOS_Msk          (0x1UL << ADC_ISR_JEOS_Pos)            /*!< 0x00000040 */
#define ADC_ISR_JEOS              ADC_ISR_JEOS_Msk                       /*!< Injected channel end of sequence flag */
#define ADC_ISR_AWD1_Pos          (7U)
#define ADC_ISR_AWD1_Msk          (0x1UL << ADC_ISR_AWD1_Pos)            /*!< 0x00000080 */
#define ADC_ISR_AWD1              ADC_ISR_AWD1_Msk                       /*!< Analog watchdog 1 flag */
#define ADC_ISR_AWD2_Pos          (8U)
#define ADC_ISR_AWD2_Msk          (0x1UL << ADC_ISR_AWD2_Pos)            /*!< 0x00000100 */
#define ADC_ISR_AWD2              ADC_ISR_AWD2_Msk                       /*!< Analog watchdog 2 flag */
#define ADC_ISR_AWD3_Pos          (9U)
#define ADC_ISR_AWD3_Msk          (0x1UL << ADC_ISR_AWD3_Pos)            /*!< 0x00000200 */
#define ADC_ISR_AWD3              ADC_ISR_AWD3_Msk                       /*!< Analog watchdog 3 flag */
#define ADC_ISR_JQOVF_Pos         (10U)
#define ADC_ISR_JQOVF_Msk         (0x1UL << ADC_ISR_JQOVF_Pos)           /*!< 0x00000400 */
#define ADC_ISR_JQOVF             ADC_ISR_JQOVF_Msk                      /*!< Injected context queue overflow */
#define ADC_ISR_LDORDY_Pos        (12U)
#define ADC_ISR_LDORDY_Msk        (0x1UL << ADC_ISR_LDORDY_Pos)          /*!< 0x00001000 */
#define ADC_ISR_LDORDY            ADC_ISR_LDORDY_Msk                     /*!< ADC internal voltage regulator output
                                                                              ready flag */

/* *************************************  Bit definition for ADC_IER register  ************************************** */
#define ADC_IER_ADRDYIE_Pos       (0U)
#define ADC_IER_ADRDYIE_Msk       (0x1UL << ADC_IER_ADRDYIE_Pos)         /*!< 0x00000001 */
#define ADC_IER_ADRDYIE           ADC_IER_ADRDYIE_Msk                    /*!< ADC ready interrupt enable */
#define ADC_IER_EOSMPIE_Pos       (1U)
#define ADC_IER_EOSMPIE_Msk       (0x1UL << ADC_IER_EOSMPIE_Pos)         /*!< 0x00000002 */
#define ADC_IER_EOSMPIE           ADC_IER_EOSMPIE_Msk                    /*!< End of sampling flag interrupt enable for
                                                                              regular conversions */
#define ADC_IER_EOCIE_Pos         (2U)
#define ADC_IER_EOCIE_Msk         (0x1UL << ADC_IER_EOCIE_Pos)           /*!< 0x00000004 */
#define ADC_IER_EOCIE             ADC_IER_EOCIE_Msk                      /*!< End of regular conversion interrupt enable
                                                                              */
#define ADC_IER_EOSIE_Pos         (3U)
#define ADC_IER_EOSIE_Msk         (0x1UL << ADC_IER_EOSIE_Pos)           /*!< 0x00000008 */
#define ADC_IER_EOSIE             ADC_IER_EOSIE_Msk                      /*!< End of regular sequence of conversions
                                                                              interrupt enable */
#define ADC_IER_OVRIE_Pos         (4U)
#define ADC_IER_OVRIE_Msk         (0x1UL << ADC_IER_OVRIE_Pos)           /*!< 0x00000010 */
#define ADC_IER_OVRIE             ADC_IER_OVRIE_Msk                      /*!< Overrun interrupt enable */
#define ADC_IER_JEOCIE_Pos        (5U)
#define ADC_IER_JEOCIE_Msk        (0x1UL << ADC_IER_JEOCIE_Pos)          /*!< 0x00000020 */
#define ADC_IER_JEOCIE            ADC_IER_JEOCIE_Msk                     /*!< End of injected conversion interrupt
                                                                              enable */
#define ADC_IER_JEOSIE_Pos        (6U)
#define ADC_IER_JEOSIE_Msk        (0x1UL << ADC_IER_JEOSIE_Pos)          /*!< 0x00000040 */
#define ADC_IER_JEOSIE            ADC_IER_JEOSIE_Msk                     /*!< End of injected sequence of conversions
                                                                              interrupt enable */
#define ADC_IER_AWD1IE_Pos        (7U)
#define ADC_IER_AWD1IE_Msk        (0x1UL << ADC_IER_AWD1IE_Pos)          /*!< 0x00000080 */
#define ADC_IER_AWD1IE            ADC_IER_AWD1IE_Msk                     /*!< Analog watchdog 1 interrupt enable */
#define ADC_IER_AWD2IE_Pos        (8U)
#define ADC_IER_AWD2IE_Msk        (0x1UL << ADC_IER_AWD2IE_Pos)          /*!< 0x00000100 */
#define ADC_IER_AWD2IE            ADC_IER_AWD2IE_Msk                     /*!< Analog watchdog 2 interrupt enable */
#define ADC_IER_AWD3IE_Pos        (9U)
#define ADC_IER_AWD3IE_Msk        (0x1UL << ADC_IER_AWD3IE_Pos)          /*!< 0x00000200 */
#define ADC_IER_AWD3IE            ADC_IER_AWD3IE_Msk                     /*!< Analog watchdog 3 interrupt enable */
#define ADC_IER_JQOVFIE_Pos       (10U)
#define ADC_IER_JQOVFIE_Msk       (0x1UL << ADC_IER_JQOVFIE_Pos)         /*!< 0x00000400 */
#define ADC_IER_JQOVFIE           ADC_IER_JQOVFIE_Msk                    /*!< Injected context queue overflow interrupt
                                                                              enable */
#define ADC_IER_LDORDYIE_Pos      (12U)
#define ADC_IER_LDORDYIE_Msk      (0x1UL << ADC_IER_LDORDYIE_Pos)        /*!< 0x00001000 */
#define ADC_IER_LDORDYIE          ADC_IER_LDORDYIE_Msk                   /*!< ADC internal voltage regulator interrupt
                                                                              enable */

/* **************************************  Bit definition for ADC_CR register  ************************************** */
#define ADC_CR_ADEN_Pos           (0U)
#define ADC_CR_ADEN_Msk           (0x1UL << ADC_CR_ADEN_Pos)             /*!< 0x00000001 */
#define ADC_CR_ADEN               ADC_CR_ADEN_Msk                        /*!< ADC enable control */
#define ADC_CR_ADDIS_Pos          (1U)
#define ADC_CR_ADDIS_Msk          (0x1UL << ADC_CR_ADDIS_Pos)            /*!< 0x00000002 */
#define ADC_CR_ADDIS              ADC_CR_ADDIS_Msk                       /*!< ADC disable command */
#define ADC_CR_ADSTART_Pos        (2U)
#define ADC_CR_ADSTART_Msk        (0x1UL << ADC_CR_ADSTART_Pos)          /*!< 0x00000004 */
#define ADC_CR_ADSTART            ADC_CR_ADSTART_Msk                     /*!< ADC start of regular conversion */
#define ADC_CR_JADSTART_Pos       (3U)
#define ADC_CR_JADSTART_Msk       (0x1UL << ADC_CR_JADSTART_Pos)         /*!< 0x00000008 */
#define ADC_CR_JADSTART           ADC_CR_JADSTART_Msk                    /*!< ADC start of injected conversion */
#define ADC_CR_ADSTP_Pos          (4U)
#define ADC_CR_ADSTP_Msk          (0x1UL << ADC_CR_ADSTP_Pos)            /*!< 0x00000010 */
#define ADC_CR_ADSTP              ADC_CR_ADSTP_Msk                       /*!< ADC stop of regular conversion command */
#define ADC_CR_JADSTP_Pos         (5U)
#define ADC_CR_JADSTP_Msk         (0x1UL << ADC_CR_JADSTP_Pos)           /*!< 0x00000020 */
#define ADC_CR_JADSTP             ADC_CR_JADSTP_Msk                      /*!< ADC stop of injected conversion command */
#define ADC_CR_ADVREGEN_Pos       (28U)
#define ADC_CR_ADVREGEN_Msk       (0x1UL << ADC_CR_ADVREGEN_Pos)         /*!< 0x10000000 */
#define ADC_CR_ADVREGEN           ADC_CR_ADVREGEN_Msk                    /*!< ADC internal voltage regulator enable */
#define ADC_CR_DEEPPWD_Pos        (29U)
#define ADC_CR_DEEPPWD_Msk        (0x1UL << ADC_CR_DEEPPWD_Pos)          /*!< 0x20000000 */
#define ADC_CR_DEEPPWD            ADC_CR_DEEPPWD_Msk                     /*!< Deep-power-down enable */
#define ADC_CR_ADCALDIF_Pos       (30U)
#define ADC_CR_ADCALDIF_Msk       (0x1UL << ADC_CR_ADCALDIF_Pos)         /*!< 0x40000000 */
#define ADC_CR_ADCALDIF           ADC_CR_ADCALDIF_Msk                    /*!< Differential mode for calibration */
#define ADC_CR_ADCAL_Pos          (31U)
#define ADC_CR_ADCAL_Msk          (0x1UL << ADC_CR_ADCAL_Pos)            /*!< 0x80000000 */
#define ADC_CR_ADCAL              ADC_CR_ADCAL_Msk                       /*!< ADC calibration */

/* ************************************  Bit definition for ADC_CFGR1 register  ************************************* */
#define ADC_CFGR1_DMNGT_Pos       (0U)
#define ADC_CFGR1_DMNGT_Msk       (0x3UL << ADC_CFGR1_DMNGT_Pos)         /*!< 0x00000003 */
#define ADC_CFGR1_DMNGT           ADC_CFGR1_DMNGT_Msk                    /*!< Data management configuration */
#define ADC_CFGR1_DMNGT_0         (0x1UL << ADC_CFGR1_DMNGT_Pos)         /*!< 0x00000001 */
#define ADC_CFGR1_DMNGT_1         (0x2UL << ADC_CFGR1_DMNGT_Pos)         /*!< 0x00000002 */
#define ADC_CFGR1_RES_Pos         (2U)
#define ADC_CFGR1_RES_Msk         (0x3UL << ADC_CFGR1_RES_Pos)           /*!< 0x0000000C */
#define ADC_CFGR1_RES             ADC_CFGR1_RES_Msk                      /*!< Data resolution */
#define ADC_CFGR1_RES_0           (0x1UL << ADC_CFGR1_RES_Pos)           /*!< 0x00000004 */
#define ADC_CFGR1_RES_1           (0x2UL << ADC_CFGR1_RES_Pos)           /*!< 0x00000008 */
#define ADC_CFGR1_EXTSEL_Pos      (5U)
#define ADC_CFGR1_EXTSEL_Msk      (0x1FUL << ADC_CFGR1_EXTSEL_Pos)       /*!< 0x000003E0 */
#define ADC_CFGR1_EXTSEL          ADC_CFGR1_EXTSEL_Msk                   /*!< External trigger selection for regular
                                                                              group */
#define ADC_CFGR1_EXTSEL_0        (0x1UL << ADC_CFGR1_EXTSEL_Pos)        /*!< 0x00000020 */
#define ADC_CFGR1_EXTSEL_1        (0x2UL << ADC_CFGR1_EXTSEL_Pos)        /*!< 0x00000040 */
#define ADC_CFGR1_EXTSEL_2        (0x4UL << ADC_CFGR1_EXTSEL_Pos)        /*!< 0x00000080 */
#define ADC_CFGR1_EXTSEL_3        (0x8UL << ADC_CFGR1_EXTSEL_Pos)        /*!< 0x00000100 */
#define ADC_CFGR1_EXTSEL_4        (0x10UL << ADC_CFGR1_EXTSEL_Pos)       /*!< 0x00000200 */
#define ADC_CFGR1_EXTEN_Pos       (10U)
#define ADC_CFGR1_EXTEN_Msk       (0x3UL << ADC_CFGR1_EXTEN_Pos)         /*!< 0x00000C00 */
#define ADC_CFGR1_EXTEN           ADC_CFGR1_EXTEN_Msk                    /*!< External trigger enable and polarity
                                                                              selection for regular channels */
#define ADC_CFGR1_EXTEN_0         (0x1UL << ADC_CFGR1_EXTEN_Pos)         /*!< 0x00000400 */
#define ADC_CFGR1_EXTEN_1         (0x2UL << ADC_CFGR1_EXTEN_Pos)         /*!< 0x00000800 */
#define ADC_CFGR1_OVRMOD_Pos      (12U)
#define ADC_CFGR1_OVRMOD_Msk      (0x1UL << ADC_CFGR1_OVRMOD_Pos)        /*!< 0x00001000 */
#define ADC_CFGR1_OVRMOD          ADC_CFGR1_OVRMOD_Msk                   /*!< Overrun mode */
#define ADC_CFGR1_CONT_Pos        (13U)
#define ADC_CFGR1_CONT_Msk        (0x1UL << ADC_CFGR1_CONT_Pos)          /*!< 0x00002000 */
#define ADC_CFGR1_CONT            ADC_CFGR1_CONT_Msk                     /*!< Single / continuous conversion mode for
                                                                              regular conversions */
#define ADC_CFGR1_AUTDLY_Pos      (14U)
#define ADC_CFGR1_AUTDLY_Msk      (0x1UL << ADC_CFGR1_AUTDLY_Pos)        /*!< 0x00004000 */
#define ADC_CFGR1_AUTDLY          ADC_CFGR1_AUTDLY_Msk                   /*!< Delayed conversion mode */
#define ADC_CFGR1_DISCEN_Pos      (16U)
#define ADC_CFGR1_DISCEN_Msk      (0x1UL << ADC_CFGR1_DISCEN_Pos)        /*!< 0x00010000 */
#define ADC_CFGR1_DISCEN          ADC_CFGR1_DISCEN_Msk                   /*!< Discontinuous mode for regular channels */
#define ADC_CFGR1_DISCNUM_Pos     (17U)
#define ADC_CFGR1_DISCNUM_Msk     (0x7UL << ADC_CFGR1_DISCNUM_Pos)       /*!< 0x000E0000 */
#define ADC_CFGR1_DISCNUM         ADC_CFGR1_DISCNUM_Msk                  /*!< Discontinuous mode channel count */
#define ADC_CFGR1_DISCNUM_0       (0x1UL << ADC_CFGR1_DISCNUM_Pos)       /*!< 0x00020000 */
#define ADC_CFGR1_DISCNUM_1       (0x2UL << ADC_CFGR1_DISCNUM_Pos)       /*!< 0x00040000 */
#define ADC_CFGR1_DISCNUM_2       (0x4UL << ADC_CFGR1_DISCNUM_Pos)       /*!< 0x00080000 */
#define ADC_CFGR1_JDISCEN_Pos     (20U)
#define ADC_CFGR1_JDISCEN_Msk     (0x1UL << ADC_CFGR1_JDISCEN_Pos)       /*!< 0x00100000 */
#define ADC_CFGR1_JDISCEN         ADC_CFGR1_JDISCEN_Msk                  /*!< Discontinuous mode on injected channels */
#define ADC_CFGR1_JQM_Pos         (21U)
#define ADC_CFGR1_JQM_Msk         (0x1UL << ADC_CFGR1_JQM_Pos)           /*!< 0x00200000 */
#define ADC_CFGR1_JQM             ADC_CFGR1_JQM_Msk                      /*!< ADC_JSQR queue mode */
#define ADC_CFGR1_AWD1SGL_Pos     (22U)
#define ADC_CFGR1_AWD1SGL_Msk     (0x1UL << ADC_CFGR1_AWD1SGL_Pos)       /*!< 0x00400000 */
#define ADC_CFGR1_AWD1SGL         ADC_CFGR1_AWD1SGL_Msk                  /*!< Enable the watchdog 1 on a single channel
                                                                              or on all channels */
#define ADC_CFGR1_AWD1EN_Pos      (23U)
#define ADC_CFGR1_AWD1EN_Msk      (0x1UL << ADC_CFGR1_AWD1EN_Pos)        /*!< 0x00800000 */
#define ADC_CFGR1_AWD1EN          ADC_CFGR1_AWD1EN_Msk                   /*!< Analog watchdog 1 enable on regular
                                                                              channels */
#define ADC_CFGR1_JAWD1EN_Pos     (24U)
#define ADC_CFGR1_JAWD1EN_Msk     (0x1UL << ADC_CFGR1_JAWD1EN_Pos)       /*!< 0x01000000 */
#define ADC_CFGR1_JAWD1EN         ADC_CFGR1_JAWD1EN_Msk                  /*!< Analog watchdog 1 enable on injected
                                                                              channels */
#define ADC_CFGR1_JAUTO_Pos       (25U)
#define ADC_CFGR1_JAUTO_Msk       (0x1UL << ADC_CFGR1_JAUTO_Pos)         /*!< 0x02000000 */
#define ADC_CFGR1_JAUTO           ADC_CFGR1_JAUTO_Msk                    /*!< Automatic injected group conversion */
#define ADC_CFGR1_AWD1CH_Pos      (26U)
#define ADC_CFGR1_AWD1CH_Msk      (0x1FUL << ADC_CFGR1_AWD1CH_Pos)       /*!< 0x7C000000 */
#define ADC_CFGR1_AWD1CH          ADC_CFGR1_AWD1CH_Msk                   /*!< Analog watchdog 1 channel selection */
#define ADC_CFGR1_AWD1CH_0        (0x1UL << ADC_CFGR1_AWD1CH_Pos)        /*!< 0x04000000 */
#define ADC_CFGR1_AWD1CH_1        (0x2UL << ADC_CFGR1_AWD1CH_Pos)        /*!< 0x08000000 */
#define ADC_CFGR1_AWD1CH_2        (0x4UL << ADC_CFGR1_AWD1CH_Pos)        /*!< 0x10000000 */
#define ADC_CFGR1_AWD1CH_3        (0x8UL << ADC_CFGR1_AWD1CH_Pos)        /*!< 0x20000000 */
#define ADC_CFGR1_AWD1CH_4        (0x10UL << ADC_CFGR1_AWD1CH_Pos)       /*!< 0x40000000 */
#define ADC_CFGR1_JQDIS_Pos       (31U)
#define ADC_CFGR1_JQDIS_Msk       (0x1UL << ADC_CFGR1_JQDIS_Pos)         /*!< 0x80000000 */
#define ADC_CFGR1_JQDIS           ADC_CFGR1_JQDIS_Msk                    /*!< Injected queue disable */

/* ************************************  Bit definition for ADC_CFGR2 register  ************************************* */
#define ADC_CFGR2_ROVSE_Pos       (0U)
#define ADC_CFGR2_ROVSE_Msk       (0x1UL << ADC_CFGR2_ROVSE_Pos)         /*!< 0x00000001 */
#define ADC_CFGR2_ROVSE           ADC_CFGR2_ROVSE_Msk                    /*!< Regular oversampling enable */
#define ADC_CFGR2_PDIFF_Pos       (2U)
#define ADC_CFGR2_PDIFF_Msk       (0x1UL << ADC_CFGR2_PDIFF_Pos)         /*!< 0x00000004 */
#define ADC_CFGR2_PDIFF           ADC_CFGR2_PDIFF_Msk                    /*!< Pseudodifferential mode enable */
#define ADC_CFGR2_PDIFFREF_Pos    (3U)
#define ADC_CFGR2_PDIFFREF_Msk    (0x1UL << ADC_CFGR2_PDIFFREF_Pos)      /*!< 0x00000008 */
#define ADC_CFGR2_PDIFFREF        ADC_CFGR2_PDIFFREF_Msk                 /*!< Pseudodifferential mode reference voltage
                                                                              selection */
#define ADC_CFGR2_OVSS_Pos        (5U)
#define ADC_CFGR2_OVSS_Msk        (0xFUL << ADC_CFGR2_OVSS_Pos)          /*!< 0x000001E0 */
#define ADC_CFGR2_OVSS            ADC_CFGR2_OVSS_Msk                     /*!< Oversampling shift */
#define ADC_CFGR2_OVSS_0          (0x1UL << ADC_CFGR2_OVSS_Pos)          /*!< 0x00000020 */
#define ADC_CFGR2_OVSS_1          (0x2UL << ADC_CFGR2_OVSS_Pos)          /*!< 0x00000040 */
#define ADC_CFGR2_OVSS_2          (0x4UL << ADC_CFGR2_OVSS_Pos)          /*!< 0x00000080 */
#define ADC_CFGR2_OVSS_3          (0x8UL << ADC_CFGR2_OVSS_Pos)          /*!< 0x00000100 */
