#define FLASH_EDATA_PAGE_SIZE   (0x1800U)                                        /*!< Flash Data Page Size: 6 KB */
#define FLASH_EDATA_PAGE_NB     (FLASH_EDATA_BANK_SIZE / FLASH_EDATA_PAGE_SIZE)  /*!< Number of FLASH EDATA pages per
                                                                                      bank */

