#define PKA_MODE_COMPARISON                (PKA_CR_MODE_2 | PKA_CR_MODE_3)                                                 /*!< Comparison */
#define PKA_MODE_MODULAR_REDUC             (PKA_CR_MODE_0 | PKA_CR_MODE_2 | PKA_CR_MODE_3)                                 /*!< Modular reduction */
#define PKA_MODE_MODULAR_ADD               (PKA_CR_MODE_1 | PKA_CR_MODE_2 | PKA_CR_MODE_3)                                 /*!< Modular addition */
#define PKA_MODE_MODULAR_SUB               (PKA_CR_MODE_0 | PKA_CR_MODE_1 | PKA_CR_MODE_2 | PKA_CR_MODE_3)                 /*!< Modular subtraction */
#define PKA_MODE_MONTGOMERY_MUL            (PKA_CR_MODE_4)                                                                 /*!< Montgomery multiplication */
#define PKA_MODE_DOUBLE_BASE_LADDER        (PKA_CR_MODE_0 | PKA_CR_MODE_1 | PKA_CR_MODE_2 | PKA_CR_MODE_5)                 /*!< Double base ladder */
#define PKA_MODE_ECC_PROJECTIVE_AFF        (PKA_CR_MODE_0 | PKA_CR_MODE_1 | PKA_CR_MODE_2 | PKA_CR_MODE_3 | PKA_CR_MODE_5) /*!< ECC projective to affine */
#define PKA_MODE_RSA_SIGNATURE             (0x00000000U)                                                                   /*!< RSA signature  */
